<script setup lang="ts">
import { computed, ref, onMounted, onBeforeUnmount, watch, nextTick } from 'vue'
import { mountChartMotion, type ChartMotion } from './chart-motion'
const dataset=ref('A'),state=ref('ready'),selected=ref(0),root=ref<HTMLElement|null>(null)
let motion:ChartMotion|undefined
onMounted(()=>{if(root.value)motion=mountChartMotion(root.value,'.hmusage-card')})
watch([dataset,state],async()=>{await nextTick();motion?.refresh()})
onBeforeUnmount(()=>motion?.destroy())
const days=['Mon','Tue','Wed'],hours=['06h','10h','14h','18h'],bands=['0–24%','25–49%','50–74%','75–100%']
const values=computed<(number|null)[]>(()=>dataset.value==='A'?[0,24,25,49,50,74,75,100,null,10,null,90]:dataset.value==='B'?[100,75,74,50,49,25,24,0,60,null,30,null]:Array(12).fill(null))
const band=(v:number|null)=>v===null?'missing':Math.min(3,Math.floor(v/25))
const text=(v:number|null)=>v===null?'Missing':v+'%'
const name=(i:number)=>`${days[Math.floor(i/4)]} ${hours[i%4]}`
function reset(){dataset.value='A';state.value='ready';selected.value=0}
</script>
<template>
<section ref="root" class="hmusage-demo" aria-label="Local heatmap example"><p>Synthetic occupancy snapshots, not hourly averages. Rows are days; columns are local observation times. Fixed threshold colors use 0–100%. Missing observations are hatched and never converted to zero.</p><div class="hmusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="missing">All missing</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><div class="hmusage-card"><template v-if="state==='ready'"><p>Observed cells: {{ values.filter(v=>v!==null).length }} / 12. No row or column normalization.</p><div class="hmusage-grid" role="group" aria-label="Select day and time"><span aria-hidden="true"></span><span v-for="h in hours" :key="h" class="hmusage-axis">{{ h }}</span><template v-for="(d,r) in days" :key="d"><span class="hmusage-axis">{{ d }}</span><button v-for="(h,c) in hours" :key="h" type="button" class="hmusage-cell" :class="['hmusage-band-'+band(values[r*4+c]),{selected:selected===r*4+c}]" :data-index="r*4+c" :data-band="band(values[r*4+c])" :aria-label="name(r*4+c)+': '+text(values[r*4+c])" :aria-pressed="selected===r*4+c" data-cm="fade" @focus="selected=r*4+c" @click="selected=r*4+c">{{ values[r*4+c]===null?'N/A':values[r*4+c]+'%' }}</button></template></div><ul class="hmusage-legend" aria-label="Fixed occupancy thresholds"><li v-for="(b,i) in bands" :key="b"><i :class="'hmusage-band-'+i" aria-hidden="true"></i>{{ b }}</li><li><i class="hmusage-band-missing" aria-hidden="true"></i>Missing</li></ul><p role="status">{{ name(selected) }}: {{ text(values[selected]) }}. {{ values[selected]===null?'No observation; no numeric band.':'Band '+bands[band(values[selected]) as number]+'.' }}</p><table class="hmusage-data"><caption>Exact occupancy snapshots, dataset {{ dataset }}</caption><thead><tr><th scope="col">Day</th><th v-for="h in hours" :key="h" scope="col">{{ h }}</th></tr></thead><tbody><tr v-for="(d,r) in days" :key="d"><th scope="row">{{ d }}</th><td v-for="(h,c) in hours" :key="h">{{ text(values[r*4+c]) }}</td></tr></tbody></table><p class="hmusage-key">A measured 0% is observed and uses the lightest band. Missing has no numeric value. All missing retains the known 3×4 grid; Empty withholds the record set. Selection changes the outline/readout, never occupancy or thresholds.</p></template><p v-else role="status" class="hmusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Observations are withheld.':'No snapshot records in this demonstration state. Choose Ready to recover.' }}</p></div></section>
</template>
<style scoped>
.hmusage-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.hmusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.hmusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.hmusage-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.hmusage-demo button{padding:6px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.hmusage-demo :is(button,select):focus-visible{outline:3px solid var(--vp-c-text-1);outline-offset:3px}.hmusage-grid{display:grid;grid-template-columns:36px repeat(4,minmax(0,1fr));gap:6px;margin:20px 0;align-items:center}.hmusage-axis{font-size:12px;text-align:center}.hmusage-demo .hmusage-cell{min-height:44px;font-size:12px;color:#09252e;border:2px solid transparent;border-radius:6px;cursor:pointer}.hmusage-demo .hmusage-cell.selected{border-color:var(--vp-c-text-1);outline:1px solid var(--vp-c-bg);outline-offset:-4px}.hmusage-demo .hmusage-band-0{background:#e0f2fe}.hmusage-demo .hmusage-band-1{background:#7dd3fc}.hmusage-demo .hmusage-band-2{background:#0369a1;color:white}.hmusage-demo .hmusage-band-3{background:#082f49;color:white}.hmusage-demo .hmusage-band-missing{background:repeating-linear-gradient(135deg,#f1f5f9 0 4px,#cbd5e1 4px 6px);color:#09252e}.hmusage-legend{display:flex;gap:8px 14px;flex-wrap:wrap;list-style:none!important;padding:0!important;font-size:12px}.hmusage-legend li{display:flex;gap:6px;align-items:center;margin:0!important}.hmusage-legend i{width:16px;height:16px;border:1px solid #64748b;display:inline-block}.hmusage-data{display:table!important;width:100%;font-size:12px}.hmusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.hmusage-data :is(td,th){padding:6px!important}.hmusage-key{font-size:12px;color:var(--vp-c-text-2)}.hmusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}
</style>
